# Break in for loop:
for i in range(10):
    if i == 5:
        break
    print(i, end=" ")  # 0 1 2 3 4

# Break in nested loops (only breaks innermost):
for i in range(3):
    for j in range(3):
        if j == 1:
            break
        print(f"({i},{j})", end=" ")  # (0,0) (1,0) (2,0)

